'use strict';
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const root=path.resolve(__dirname,'../..');
const policy=require('../../js/renaigame_policy.js');
const scope={window:{RenaiGamePolicy:policy}};
vm.runInNewContext(fs.readFileSync(path.join(root,'js/renaigame_psychology_parameters.js'),'utf8'),scope);
function render(contract=policy,psychology=scope.window.RenaiGamePsychologyParameters){
  const fields=contract.requiredPsychologyFields(psychology);
  const c=contract.chapter;
  return [
    '# 共通規則の自動生成リファレンス','',
    '<!-- Generated by simulation/scripts/generate_policy_reference.cjs. Do not edit. -->','',
    '機械処理の正本は`js/renaigame_policy.js`。心理項目の定義は`js/renaigame_psychology_parameters.js`の`stateDefaults`。',
    '段階・補正・形式・意味確認軸を個別ファイルで再定義しない。変更後は`node simulation/scripts/generate_policy_reference.cjs`でこの説明を再生成する。',
    '公開前の一括検査：`node simulation/scripts/check_ai_turn.cjs`。CIはこの説明と正本の不一致を拒否する。','',
    '## 恋愛段階','',
    '| 番号 | 段階 | 互換名 | seekHeroine下限 |',
    '|---|---|---|---|',
    ...contract.stages.map(s=>'| '+[s.id,s.name,s.aliases.join('・')||'なし',s.seekHeroineFloor].join(' | ')+' |'),'',
    '初期段階も恋愛を主軸とする。段階は表し方の資料であり、主人公の意思・反応を補完しない。','',
    '## 全攻略対象・全主人公の進行方針','',
    contract.storyDirection.protagonistCare,'',
    contract.storyDirection.instruction,'',
    contract.storyDirection.beforeDraft,'',
    contract.storyDirection.turnInstruction,'',
    contract.storyDirection.expressionRule,'',
    contract.storyDirection.sourcePriority,'',
    ...Object.entries(contract.storyDirection.reviewGuidance).map(([axis,guidance])=>'- `'+axis+'`：'+guidance),'',
    '## 恋愛相手自身の感情','',
    contract.partnerEmotion.instruction,'',
    '`sceneEmotion`の確認：'+contract.literaryReview.guidance.sceneEmotion,'',
    '## 選択中の相手の呼称','',
    '正式名・従来の短名に加え、次の登録呼称を同一人物として照合する。敬称・英字の大小・空白の表記差を許容し、本文や計算パケットは変更しない。別人や曖昧な役職だけで代用しない。','',
    '| 人物ID | 登録呼称 |','|---|---|',
    ...Object.entries(contract.actorAliases).map(([id,names])=>'| '+id+' | '+names.join('・')+' |'),'',
    '## 心理値の欠落','',
    '計算前に次の'+fields.length+'数値項目を検査する。欠落・null・数値文字列・非有限値は0で埋めず、同じスロットの実ログに基づく移行が必要と報告する。正本を自動で変更しない。','',
    '`'+fields.join(' / ')+'`','',
    '## 標準の章JSON','',
    '心理付き章はversion '+c.version+'。通常はAIが検証済みの今回1章JSONを出力し、ゲームが再計算・指紋照合後に保存する。AIの直接書込みはユーザーが明示した場合だけ試す。',
    '恋愛相手未選択は`CHAPTER_SAVE_FORMAT.md`の専用規定を使う。','',
    '- ルート：`'+c.rootFields.join(' / ')+'`',
    '- 本文：`'+c.recordFields.join(' / ')+'`',
    '- 心理履歴：`'+c.historyFields.join(' / ')+'`',
    '- 再検証：`'+c.replayFields.join(' / ')+'`',
    '- 心理履歴への展開禁止：`'+c.historyForbidden.join(' / ')+'`',
    '- ファイル名：`'+c.filenamePattern+'`','',
    '同内容の再取り込みは重複追加しない。異なる保存済み同章は上書き・統合しない。続きを進める場合は次のChapterとして計算・検証する。','',
    '## 本文の意味確認','',
    '新規生成の意味確認票はversion '+contract.storyDirection.reviewVersion+'。章JSONのversionとは別。作成済みの旧票は元のbindingと条件で再検証し、新しい本文の出力には流用しない。','',
    ...contract.reviewAxes.map(axis=>'- `'+axis+'`'),'',
    '小説としての仕上げは`'+contract.literaryReview.axis+'`で全章必須。`revisionNote`に改稿内容または修正不要の理由、`aspects`に次の各項目のpass・理由・最終本文の引用を記録する。',
    ...contract.literaryReview.aspects.map(aspect=>'- `'+aspect+'`'),'',
    '原文と正本を下書き後に別工程で照合し、根拠を記録する。確認票を自動で全passにしない。機械検査だけを意味の保証にせず、releaseStoryが返した本文だけを出す。',
    '未検証・指示違反の誤生成を、出力済みという理由で確定した出来事にしない。保存済み実ログは無断で変更しない。',''
  ].join('\n');
}
function main(args){
  if(args.length>1 || (args.length===1 && args[0]!=='--check')) throw Error('使い方: node simulation/scripts/generate_policy_reference.cjs [--check]');
  const file=path.join(root,'simulation/AI_POLICY_REFERENCE.md'),content=render();
  if(args[0]==='--check'){
    if(!fs.existsSync(file)||fs.readFileSync(file,'utf8')!==content) throw Error('規則の説明と正本が不一致です。generate_policy_reference.cjsで再生成してください。');
    console.log('PASS: generated policy reference matches the executable source');
  }else fs.writeFileSync(file,content);
}
if(require.main===module){try{main(process.argv.slice(2));}catch(error){console.error(error.message);process.exitCode=1;}}
module.exports={render,main};
